// Ground-truth fingerprints extracted offline from exact/symbolized Nintendo SDK builds.
// Absolute addresses and raw executable bytes are intentionally not embedded.
// Sources: Pikmin, Mario Kart: Double Dash!!, Super Mario Sunshine, Pokemon XD,
// Paper Mario: The Thousand-Year Door, Medal of Honor: European Assault,
// Medal of Honor: Frontline, and Medal of Honor: Rising Sun. Addresses never
// participate in runtime matching.
// source_variant: 0=Pikmin, 1=MKDD, 2=SMS, 3=Pokemon XD, 4=Paper Mario TTYD,
// 5=MOH European Assault (GONE69), 6=MOH Frontline (GMFE69),
// 7=MOH Rising Sun (GR8E69; RDC/RDVD treated as one SDK family),
// 8=King Kong (verification-only: no novel body), 9=007 Agent Under Fire,
// 10=Top Gun: Combat Zones, 11=Scooby-Doo! Mystery Mayhem,
// 12=Scooby-Doo! Unmasked (verification-only), 13=Terminator 3: The Redemption,
// 14=The Legend of Spyro (verification-only), 15=The Sims 2,
// 16=Animal Crossing, 17=Spyro: A Hero's Tail (verification-only),
// 18=GoldenEye: Rogue Agent (GOYE69; verification-only),
// 19=Finding Nemo (GNEE78), 20=Cars (GKJE78; verification-only),
// 21=NFS Underground (GNDE69; verification-only), 22=NFS Underground preview (GNDP8P),
// 23=NFS Underground 2 (GUYE69; verification-only),
// 24=NFS Most Wanted (GOWE69; verification-only).
// Duplicate bodies from independent builds are not stored again; the source
// corpus is used offline to validate identity uniqueness without bloating runtime matching.
struct GroundTruthExemplar {
  std::string_view name;
  bool critical = false;
  std::uint32_t skeleton_offset = 0;
  std::uint16_t skeleton_count = 0;
  std::uint16_t call_offset = 0;
  std::uint16_t call_count = 0;
  std::int32_t stack_frame = 0;
  std::uint8_t source_variant = 0;
};

