inline std::span<const std::uint32_t> GroundTruthSkeleton(const GroundTruthExemplar& exemplar) {
  return {kGroundTruthSkeletonWords.data() + exemplar.skeleton_offset,
          exemplar.skeleton_count};
}

inline std::span<const std::string_view> GroundTruthCalls(const GroundTruthExemplar& exemplar) {
  return {kGroundTruthCallNames.data() + exemplar.call_offset,
          exemplar.call_count};
}

inline std::uint32_t GroundTruthRelaxedWord(std::uint32_t word) {
  const std::uint32_t op = word >> 26;
  if (op == 18u)
    return word & 0xfc000003u;
  if (op == 16u)
    return word & 0xffff0003u;
  // The relaxed corpus channel removes all D-form immediates, including cmpwi/
  // cmplwi. Register flow and operation class remain, but build-specific SDA,
  // structure offsets and constants cannot dominate the score.
  if (op == 10u || op == 11u || op == 14u || op == 15u ||
      op == 24u || op == 25u || (op >= 32u && op <= 47u))
    return word & 0xffff0000u;
  return word;
}

inline double GroundTruthSequenceSimilarity(std::span<const std::uint32_t> lhs,
                                            std::span<const std::uint32_t> rhs,
                                            bool relaxed,
                                            std::size_t window = 3) {
  if (lhs.empty() || rhs.empty())
    return 0.0;
  const auto small = lhs.size() <= rhs.size() ? lhs : rhs;
  const auto large = lhs.size() <= rhs.size() ? rhs : lhs;
  const bool lhs_is_small = lhs.size() <= rhs.size();
  std::size_t matches = 0;
  for (std::size_t i = 0; i < small.size(); ++i) {
    const double scaled = small.size() == 1
        ? 0.0
        : static_cast<double>(i) * static_cast<double>(large.size() - 1) /
              static_cast<double>(small.size() - 1);
    const std::size_t center = static_cast<std::size_t>(scaled + 0.5);
    const std::size_t begin = center > window ? center - window : 0;
    const std::size_t end = std::min(large.size(), center + window + 1);
    const std::uint32_t source = relaxed ? GroundTruthRelaxedWord(small[i]) : small[i];
    for (std::size_t j = begin; j < end; ++j) {
      const std::uint32_t target = relaxed ? GroundTruthRelaxedWord(large[j]) : large[j];
      if (source == target) {
        ++matches;
        break;
      }
    }
  }
  (void)lhs_is_small;
  return static_cast<double>(matches) / static_cast<double>(small.size());
}

inline const std::vector<StructuralShape>& GroundTruthShapes() {
  static const std::vector<StructuralShape> shapes = [] {
    std::vector<StructuralShape> out;
    out.reserve(kGroundTruthExemplars.size());
    for (const auto& exemplar : kGroundTruthExemplars) {
      StructuralShape shape;
      shape.size = static_cast<std::uint32_t>(exemplar.skeleton_count) * 4u;
      shape.instruction_count = exemplar.skeleton_count;
      shape.stack_frame = exemplar.stack_frame;
      const auto skeleton = GroundTruthSkeleton(exemplar);
      shape.skeleton.assign(skeleton.begin(), skeleton.end());
      for (const auto word : skeleton) {
        const auto op = word >> 26;
        ++shape.primary_ops[op];
        if (op == 18u && (word & 1u))
          ++shape.direct_calls;
        if (op == 16u || op == 18u || op == 19u)
          ++shape.branches;
        if (word == 0x4e800020u)
          ++shape.returns;
      }
      out.push_back(std::move(shape));
    }
    return out;
  }();
  return shapes;
}

inline double GroundTruthSimilarity(const StructuralShape& candidate,
                                    const StructuralShape& reference) {
  if (!candidate.instruction_count || !reference.instruction_count)
    return 0.0;
  const double size = StructuralRatio(candidate.instruction_count,
                                      reference.instruction_count);
  if (size < 0.45)
    return 0.0;
  const double histogram = StructuralHistogramSimilarity(candidate, reference);
  const double strict_sequence = StructuralSequenceSimilarity(candidate, reference);
  const double relaxed_sequence = GroundTruthSequenceSimilarity(
      candidate.skeleton, reference.skeleton, true, 3);
  const double calls = StructuralRatio(candidate.direct_calls + 1u,
                                       reference.direct_calls + 1u);
  const double branches = StructuralRatio(candidate.branches + 1u,
                                          reference.branches + 1u);
  const double frame = candidate.stack_frame == reference.stack_frame ? 1.0 :
      (candidate.stack_frame == 0 || reference.stack_frame == 0 ? 0.70 : 0.25);
  const double returns = candidate.returns == reference.returns ? 1.0 : 0.5;
  return 0.10 * size + 0.16 * histogram + 0.18 * strict_sequence +
         0.36 * relaxed_sequence + 0.08 * calls + 0.05 * branches +
         0.04 * frame + 0.03 * returns;
}

inline bool GroundTruthExact(const StructuralShape& candidate,
                             const StructuralShape& reference) {
  return candidate.skeleton == reference.skeleton;
}

inline std::size_t GroundTruthExactIdentityCount(const StructuralShape& candidate) {
  const auto& shapes = GroundTruthShapes();
  std::set<std::string_view> names;
  for (std::size_t i = 0; i < kGroundTruthExemplars.size(); ++i) {
    if (GroundTruthExact(candidate, shapes[i]))
      names.insert(kGroundTruthExemplars[i].name);
  }
  return names.size();
}

struct GroundTruthResolveStats {
  std::size_t exact = 0;
  std::size_t fuzzy = 0;
  std::size_t graph = 0;
  std::size_t ambiguous = 0;
};

inline double GroundTruthCallAgreement(const StructuralResolver& resolver,
                                       const StructuralFunction& function,
                                       const GroundTruthExemplar& exemplar,
                                       unsigned* evidence) {
  unsigned known = 0;
  unsigned matched = 0;
  for (const auto expected : GroundTruthCalls(exemplar)) {
    // Only score a reference edge once that callee identity is already known in
    // the current DOL. Missing support symbols therefore do not count against a
    // candidate during early passes.
    if (resolver.Find(expected, 0.93).empty())
      continue;
    ++known;
    if (resolver.Calls(function.address, expected, 0.93))
      ++matched;
  }
  if (evidence)
    *evidence = known;
  return known ? static_cast<double>(matched) / static_cast<double>(known) : 0.0;
}

inline GroundTruthResolveStats ResolveGroundTruthCorpus(StructuralResolver& resolver) {
  GroundTruthResolveStats stats;
  const auto& shapes = GroundTruthShapes();

  // Pass A: normalized body equality. Branch displacements, SDA addresses and
  // relocation-sensitive immediates are absent from the skeleton. An exact
  // skeleton is admitted only when the whole reference corpus agrees on ONE
  // identity. Cross-identity collisions are explicitly quarantined.
  for (const auto& [address, function] : resolver.Functions()) {
    if (resolver.Resolution(address) || resolver.IsAmbiguous(address))
      continue;
    std::set<std::string_view> names;
    for (std::size_t i = 0; i < kGroundTruthExemplars.size(); ++i) {
      if (GroundTruthExact(function.shape, shapes[i]))
        names.insert(kGroundTruthExemplars[i].name);
    }
    if (names.size() == 1) {
      if (resolver.Seed(address, std::string(*names.begin()), 0.999,
                        "groundtruth-normalized-exact"))
        ++stats.exact;
    } else if (names.size() > 1) {
      resolver.MarkAmbiguous(address);
      ++stats.ambiguous;
    }
  }

  struct Proposal {
    std::uint32_t address = 0;
    std::string_view name;
    double score = 0.0;
    double margin = 0.0;
    double confidence = 0.0;
    unsigned evidence = 0;
  };

  // Admit at most the globally best previously-unseen body for each identity.
  // Exact duplicate copies of that body may all be admitted. This prevents the
  // old failure mode where dozens of unrelated functions simultaneously became
  // OSDisableScheduler merely because each one passed a local threshold.
  const auto admit_unique = [&](std::vector<Proposal> proposals,
                                std::string_view source,
                                std::size_t* counter) {
    std::map<std::string_view, std::vector<Proposal>> by_identity;
    for (const auto& proposal : proposals)
      by_identity[proposal.name].push_back(proposal);
    for (auto& [name, candidates] : by_identity) {
      std::sort(candidates.begin(), candidates.end(),
                [](const Proposal& lhs, const Proposal& rhs) {
                  if (lhs.score != rhs.score)
                    return lhs.score > rhs.score;
                  return lhs.address < rhs.address;
                });
      if (candidates.empty())
        continue;
      const auto& best = candidates.front();
      const auto* best_fn = resolver.Function(best.address);
      if (!best_fn)
        continue;
      double second_distinct = 0.0;
      for (std::size_t i = 1; i < candidates.size(); ++i) {
        const auto* other = resolver.Function(candidates[i].address);
        if (!other || other->shape.skeleton == best_fn->shape.skeleton)
          continue;
        second_distinct = candidates[i].score;
        break;
      }
      if (second_distinct > 0.0 && best.score - second_distinct < 0.018)
        continue;

      for (const auto& candidate : candidates) {
        const auto* fn = resolver.Function(candidate.address);
        if (!fn)
          continue;
        const bool same_exact_body = fn->shape.skeleton == best_fn->shape.skeleton;
        if (candidate.address != best.address && !same_exact_body)
          continue;
        if (resolver.Seed(candidate.address, std::string(name),
                          candidate.confidence, std::string(source))) {
          if (counter)
            ++*counter;
        }
      }
    }
  };

  // Pass B: multi-build fuzzy body matching. A candidate must beat every other
  // identity by a useful margin and either agree with >=2 independent reference
  // builds or be nearly exact to one known SDK variant. Then global uniqueness
  // is enforced per identity before any symbol is renamed.
  std::vector<Proposal> fuzzy_proposals;
  for (const auto& [address, function] : resolver.Functions()) {
    if (resolver.Resolution(address) || resolver.IsAmbiguous(address) ||
        function.shape.instruction_count < 8u)
      continue;
    struct ScoreSupport { double best = 0.0; std::set<std::uint8_t> sources; };
    std::map<std::string_view, ScoreSupport> identity_score;
    for (std::size_t i = 0; i < kGroundTruthExemplars.size(); ++i) {
      const auto& exemplar = kGroundTruthExemplars[i];
      if (!exemplar.critical)
        continue;
      const double score = GroundTruthSimilarity(function.shape, shapes[i]);
      auto& aggregate = identity_score[exemplar.name];
      aggregate.best = std::max(aggregate.best, score);
      if (score >= 0.88)
        aggregate.sources.insert(exemplar.source_variant);
    }
    std::string_view best_name;
    double best = 0.0;
    double second = 0.0;
    unsigned support = 0;
    for (const auto& [name, aggregate] : identity_score) {
      const double score = aggregate.best;
      if (score > best) {
        second = best;
        best = score;
        best_name = name;
        support = static_cast<unsigned>(aggregate.sources.size());
      } else if (score > second) {
        second = score;
      }
    }
    const double margin = best - second;
    if (!best_name.empty() && best >= 0.96 && margin >= 0.045 &&
        (support >= 2 || best >= 0.985)) {
      const double confidence = std::min(0.995, 0.960 + (best - 0.96) * 0.55 +
                                                std::min(0.012, 0.004 * support));
      fuzzy_proposals.push_back(
          {address, best_name, best, margin, confidence, support});
    }
  }
  admit_unique(std::move(fuzzy_proposals), "groundtruth-fuzzy-global", &stats.fuzzy);

  // Pass C: iterative call-graph matching. Large compiler-sensitive SDK
  // routines may have substantially different bodies, but their calls into
  // already-resolved SDK primitives remain semantic evidence. Require at least
  // two resolved callees, candidate-side identity separation and global winner
  // selection. Repeat because each accepted identity can unlock the next layer.
  for (unsigned pass = 0; pass < 8; ++pass) {
    std::vector<Proposal> graph_proposals;
    for (const auto& [address, function] : resolver.Functions()) {
      if (resolver.Resolution(address) || resolver.IsAmbiguous(address) ||
          function.calls.size() < 2)
        continue;
      std::map<std::string_view, double> identity_score;
      std::map<std::string_view, unsigned> identity_evidence;
      for (std::size_t i = 0; i < kGroundTruthExemplars.size(); ++i) {
        const auto& exemplar = kGroundTruthExemplars[i];
        if (!exemplar.critical || exemplar.call_count < 2)
          continue;
        unsigned evidence = 0;
        const double graph = GroundTruthCallAgreement(resolver, function, exemplar, &evidence);
        if (evidence < 2 || graph < 0.999)
          continue;
        const double body = GroundTruthSimilarity(function.shape, shapes[i]);
        if (body < 0.24)
          continue;
        double score = 0.0;
        if (evidence >= 3)
          score = 0.78 + 0.14 * std::min(1.0, body) + 0.08 * graph;
        else if (body >= 0.55)
          score = 0.70 + 0.22 * body + 0.08 * graph;
        if (score <= 0.0)
          continue;
        auto& current = identity_score[exemplar.name];
        if (score > current) {
          current = score;
          identity_evidence[exemplar.name] = evidence;
        }
      }
      std::string_view best_name;
      double best = 0.0;
      double second = 0.0;
      unsigned evidence = 0;
      for (const auto& [name, score] : identity_score) {
        if (score > best) {
          second = best;
          best = score;
          best_name = name;
          evidence = identity_evidence[name];
        } else if (score > second) {
          second = score;
        }
      }
      const double margin = best - second;
      if (!best_name.empty() && evidence >= 2 && best >= 0.93 && margin >= 0.025)
        graph_proposals.push_back(
            {address, best_name, best, margin, std::min(0.992, best), evidence});
    }
    std::size_t added = 0;
    admit_unique(std::move(graph_proposals), "groundtruth-callgraph-global", &added);
    stats.graph += added;
    if (!added)
      break;
  }
  return stats;
}

